/* cppi::002102d7c25b0dac846dafae7070556ef8a0764ff888423a17cdaf97077f3db9 */
select 
asec.cppib_sec_id AS "cppib_security_id",
asec.cppib_currency_of_exposure_code AS "Exposure Currency"

from asset.asset_security_enterprise_classifications asec where business_date =  CAST('2025-06-05' AS DATE)

/* cppi::9696944b91f7dc4e606df5cde9e743bef7d68c81e38bbb56995d17690cebe3a8 */
select business_date as date_, security_id, 'MS757951' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-05' and business_date <= date '2025-06-05' and weight_ndo>0 and id_cppib_index = 'MS757951_GR_USD_0_0' and security_id is not null

/* cppi::0f99256ffb40d31c9e75851093ecf6108d11f6c811b2ae16361c3a681746806e */
